CREATE TYPE public.app_role AS ENUM ('admin','coordinator','agent','viewer');
CREATE TABLE public.user_roles (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL, role public.app_role NOT NULL, UNIQUE(user_id, role));
GRANT SELECT ON public.user_roles TO authenticated; GRANT ALL ON public.user_roles TO service_role;
ALTER TABLE public.user_roles ENABLE ROW LEVEL SECURITY;
CREATE POLICY "read own role" ON public.user_roles FOR SELECT TO authenticated USING (user_id = auth.uid());
CREATE FUNCTION public.has_role(_user_id uuid, _role public.app_role) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$ SELECT EXISTS(SELECT 1 FROM public.user_roles WHERE user_id = _user_id AND role = _role) $$;
CREATE TABLE public.profiles (id uuid PRIMARY KEY, full_name text NOT NULL DEFAULT '', phone text DEFAULT '', governance text DEFAULT '', region text DEFAULT '', created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, INSERT, UPDATE, DELETE ON public.profiles TO authenticated; GRANT ALL ON public.profiles TO service_role;
ALTER TABLE public.profiles ENABLE ROW LEVEL SECURITY;
CREATE POLICY "read profiles" ON public.profiles FOR SELECT TO authenticated USING (id = auth.uid() OR public.has_role(auth.uid(), 'admin') OR public.has_role(auth.uid(), 'coordinator'));
CREATE POLICY "insert own profile" ON public.profiles FOR INSERT TO authenticated WITH CHECK (id = auth.uid());
CREATE POLICY "update own profile" ON public.profiles FOR UPDATE TO authenticated USING (id = auth.uid()) WITH CHECK (id = auth.uid());
CREATE TABLE public.organizations (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), owner_id uuid NOT NULL DEFAULT auth.uid(), name text NOT NULL, kind text NOT NULL DEFAULT 'Empresa', document text DEFAULT '', sector text DEFAULT '', size text DEFAULT '', maturity text DEFAULT '', region text DEFAULT '', contact text DEFAULT '', email text DEFAULT '', phone text DEFAULT '', address text DEFAULT '', stage text NOT NULL DEFAULT 'Prospecção', demand text DEFAULT '', referral text DEFAULT '', notes text DEFAULT '', created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, INSERT, UPDATE, DELETE ON public.organizations TO authenticated; GRANT ALL ON public.organizations TO service_role;
ALTER TABLE public.organizations ENABLE ROW LEVEL SECURITY;
CREATE POLICY "read organizations" ON public.organizations FOR SELECT TO authenticated USING (owner_id = auth.uid() OR public.has_role(auth.uid(), 'admin') OR public.has_role(auth.uid(), 'coordinator') OR public.has_role(auth.uid(), 'viewer'));
CREATE POLICY "insert organizations" ON public.organizations FOR INSERT TO authenticated WITH CHECK (owner_id = auth.uid() AND NOT public.has_role(auth.uid(), 'viewer'));
CREATE POLICY "update organizations" ON public.organizations FOR UPDATE TO authenticated USING (owner_id = auth.uid() OR public.has_role(auth.uid(), 'admin') OR public.has_role(auth.uid(), 'coordinator')) WITH CHECK (owner_id = auth.uid() OR public.has_role(auth.uid(), 'admin') OR public.has_role(auth.uid(), 'coordinator'));
CREATE POLICY "delete organizations" ON public.organizations FOR DELETE TO authenticated USING (owner_id = auth.uid() OR public.has_role(auth.uid(), 'admin'));
CREATE TABLE public.actors (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), owner_id uuid NOT NULL DEFAULT auth.uid(), institution_type text NOT NULL DEFAULT '', document text DEFAULT '', institution_name text NOT NULL, phone text DEFAULT '', address text DEFAULT '', actor_name text NOT NULL, position text DEFAULT '', birth_date date, email text DEFAULT '', created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, INSERT, UPDATE, DELETE ON public.actors TO authenticated; GRANT ALL ON public.actors TO service_role;
ALTER TABLE public.actors ENABLE ROW LEVEL SECURITY;
CREATE POLICY "read actors" ON public.actors FOR SELECT TO authenticated USING (owner_id = auth.uid() OR public.has_role(auth.uid(), 'admin') OR public.has_role(auth.uid(), 'coordinator') OR public.has_role(auth.uid(), 'viewer'));
CREATE POLICY "insert actors" ON public.actors FOR INSERT TO authenticated WITH CHECK (owner_id = auth.uid() AND NOT public.has_role(auth.uid(), 'viewer'));
CREATE POLICY "update actors" ON public.actors FOR UPDATE TO authenticated USING (owner_id = auth.uid() OR public.has_role(auth.uid(), 'admin') OR public.has_role(auth.uid(), 'coordinator')) WITH CHECK (owner_id = auth.uid() OR public.has_role(auth.uid(), 'admin') OR public.has_role(auth.uid(), 'coordinator'));
CREATE POLICY "delete actors" ON public.actors FOR DELETE TO authenticated USING (owner_id = auth.uid() OR public.has_role(auth.uid(), 'admin'));
CREATE TABLE public.activities (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), owner_id uuid NOT NULL DEFAULT auth.uid(), kind text NOT NULL, title text NOT NULL, description text DEFAULT '', status text NOT NULL DEFAULT 'Não iniciada', start_date date, end_date date, organization_id uuid REFERENCES public.organizations(id) ON DELETE SET NULL, axis text DEFAULT '', problem text DEFAULT '', problem_description text DEFAULT '', solution text DEFAULT '', solution_description text DEFAULT '', objectives text DEFAULT '', expected_results text DEFAULT '', achieved_results text DEFAULT '', participants text DEFAULT '', agenda text DEFAULT '', referrals text DEFAULT '', work_done text DEFAULT '', outcomes jsonb NOT NULL DEFAULT '[]'::jsonb, evidence jsonb NOT NULL DEFAULT '[]'::jsonb, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, INSERT, UPDATE, DELETE ON public.activities TO authenticated; GRANT ALL ON public.activities TO service_role;
ALTER TABLE public.activities ENABLE ROW LEVEL SECURITY;
CREATE POLICY "read activities" ON public.activities FOR SELECT TO authenticated USING (owner_id = auth.uid() OR public.has_role(auth.uid(), 'admin') OR public.has_role(auth.uid(), 'coordinator') OR public.has_role(auth.uid(), 'viewer'));
CREATE POLICY "insert activities" ON public.activities FOR INSERT TO authenticated WITH CHECK (owner_id = auth.uid() AND NOT public.has_role(auth.uid(), 'viewer'));
CREATE POLICY "update activities" ON public.activities FOR UPDATE TO authenticated USING (owner_id = auth.uid() OR public.has_role(auth.uid(), 'admin') OR public.has_role(auth.uid(), 'coordinator')) WITH CHECK (owner_id = auth.uid() OR public.has_role(auth.uid(), 'admin') OR public.has_role(auth.uid(), 'coordinator'));
CREATE POLICY "delete activities" ON public.activities FOR DELETE TO authenticated USING (owner_id = auth.uid() OR public.has_role(auth.uid(), 'admin'));
CREATE INDEX activities_owner_date_idx ON public.activities(owner_id, start_date DESC);
CREATE INDEX organizations_owner_idx ON public.organizations(owner_id);
CREATE INDEX actors_owner_idx ON public.actors(owner_id);